import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.CNDaxUod.js";const h=JSON.parse('{"title":"Data contract for v1","description":"","frontmatter":{},"headers":[],"relativePath":"reference/data-contract-v1.md","filePath":"reference/data-contract-v1.md","lastUpdated":1788607300000}'),i={name:"reference/data-contract-v1.md"};function r(s,e,l,c,d,u){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="data-contract-for-v1" tabindex="-1">Data contract for v1 <a class="header-anchor" href="#data-contract-for-v1" aria-label="Permalink to &quot;Data contract for v1&quot;">​</a></h1><p>This document defines the target stable resume-data contract for Web Resume v1. It can be implemented during 0.x, but becomes a compatibility guarantee only when v1.0.0 is released.</p><h2 id="stable-input" tabindex="-1">Stable input <a class="header-anchor" href="#stable-input" aria-label="Permalink to &quot;Stable input&quot;">​</a></h2><ul><li>The canonical model is the JSON Resume schema bundled with the released app.</li><li>Resume data may be authored as YAML or JSON; the file syntax does not change the model.</li><li>Standard fields are preferred whenever they accurately express the content.</li><li>Web Resume presentation data uses only the root <code>x-web-resume</code> extension.</li><li><code>x-web-resume.version</code> versions the extension independently and starts at <code>1</code>.</li></ul><p>The release pins a compatible <code>@jsonresume/schema</code> minor line. Moving to an incompatible canonical schema or changing the meaning of persisted extension fields requires a Web Resume major release or an explicit migration path.</p><h2 id="compatibility-guarantees" tabindex="-1">Compatibility guarantees <a class="header-anchor" href="#compatibility-guarantees" aria-label="Permalink to &quot;Compatibility guarantees&quot;">​</a></h2><ul><li>Valid canonical documents load without requiring <code>x-web-resume</code>.</li><li>Unknown canonical fields are preserved while editing unless the user explicitly chooses Portable export.</li><li>Lossless Web Resume documents preserve section order, titles, icons, item presentation data, custom content, and footer data under <code>x-web-resume</code>.</li><li>Portable export contains only canonical fields and is validated before download.</li><li>Loading, conversion, reordering, and export never silently overwrite the original URL or disk file.</li></ul><h2 id="legacy-documents" tabindex="-1">Legacy documents <a class="header-anchor" href="#legacy-documents" aria-label="Permalink to &quot;Legacy documents&quot;">​</a></h2><p>The pre-v0.4 Web Resume structure is a compatibility input, not the v1 canonical authoring format. It remains detectable and explicitly convertible. Any future removal of direct legacy rendering must:</p><ol><li>be announced in release notes;</li><li>retain or provide a tested conversion command;</li><li>document fields that require manual review; and</li><li>ship only at a version boundary that permits the compatibility change.</li></ol><h2 id="extension-boundary" tabindex="-1">Extension boundary <a class="header-anchor" href="#extension-boundary" aria-label="Permalink to &quot;Extension boundary&quot;">​</a></h2><p><code>x-web-resume</code> may contain presentation and application-specific information, including section order, section titles and icons, item logos and badges, custom contact presentation, free-form <code>other</code> content, and footer display data. It must not duplicate standard content merely to avoid using a canonical field.</p><p>Consumers that do not understand the extension may ignore it. Users who need maximum interoperability should use Portable export; users who need Web Resume round-tripping should keep the lossless YAML or JSON source.</p>',13)])])}const p=a(i,[["render",r]]);export{h as __pageData,p as default};
